import { realpath, stat } from "node:fs/promises";
import { posix } from "node:path";
import { RUNTIME_LIMITS } from "./limits.js";
// Stock browser_file_upload's roots on a box: /workspace and its output dir,
// /workspace/.playwright-mcp, which sits inside it.
export const DEFAULT_UPLOAD_ROOTS = ["/workspace"];
const REFUSED = { kind: "refused" };
export function uploadRefusalHint(roots) {
    return `setInputFiles uploads only existing files under ${roots.join(" or ")}, by absolute path`;
}
// Both the path as written and its real path must sit under a root, so a
// symlink cannot lead in or out; the real paths are what Chrome is handed.
export async function admitUploadPaths(value, roots) {
    if (!Array.isArray(value) || value.length === 0 || value.length > RUNTIME_LIMITS.uploadPaths) {
        return REFUSED;
    }
    const realRoots = [];
    for (const root of roots) {
        const real = await realpath(root).catch(() => undefined);
        if (real !== undefined)
            realRoots.push(real);
    }
    const admitted = [];
    for (const candidate of value) {
        if (!isResolvedAbsolutePath(candidate) || !isUnder(candidate, roots))
            return REFUSED;
        const real = await realFile(candidate);
        if (real === undefined || !isUnder(real, realRoots))
            return REFUSED;
        admitted.push(real);
    }
    return { kind: "admitted", localPaths: admitted };
}
function isResolvedAbsolutePath(value) {
    return (typeof value === "string" &&
        value.length <= 4096 &&
        !value.includes("\0") &&
        posix.isAbsolute(value) &&
        posix.resolve(value) === value);
}
function isUnder(path, roots) {
    return roots.some((root) => path.startsWith(root.endsWith("/") ? root : `${root}/`));
}
async function realFile(path) {
    try {
        const real = await realpath(path);
        return (await stat(real)).isFile() ? real : undefined;
    }
    catch {
        return undefined;
    }
}
